// Authored JS surface of the WebAssembly HarfBuzz binding.
//
// This module is the stable boundary the Kotlin/JS and Kotlin/Wasm actuals call.
// It wraps the Emscripten module (`hb.mjs`, generated by
// :kffi-harfbuzz-wasm-native) and exposes a small, number-and-string surface so
// the Kotlin interop signatures stay within Kotlin/Wasm's restricted type set.
//
// It is authored, not generated: the Emscripten output may change shape between
// releases, and the Kotlin bindings must never depend on that shape directly.
//
// Loading is asynchronous — `WebAssembly.instantiate` is — so every entry point
// requires `await hbInit()` first. That is the async initialization the Kotlin
// binding surfaces through an explicit initializer.

import createHbModule from './hb.mjs';

let module = null;

/** Instantiates the bundled HarfBuzz module once; subsequent calls are a no-op. */
export async function hbInit() {
    if (module === null) {
        module = await createHbModule();
    }
    return true;
}

/** Whether `hbInit` has completed. */
export function hbReady() {
    return module !== null;
}

function requireModule() {
    if (module === null) {
        throw new Error('HarfBuzz web module is not initialized: call hbInit() first.');
    }
    return module;
}

/** The HarfBuzz version the loaded module reports. */
export function hbVersion() {
    return requireModule().ccall('hb_version_string', 'string', [], []);
}

/** Allocates `size` bytes in the module heap; the caller owns the pointer. */
export function hbAlloc(size) {
    return requireModule()._malloc(size);
}

/** Frees a pointer previously returned by `hbAlloc`. */
export function hbFree(pointer) {
    requireModule()._free(pointer);
}

/**
 * Copies a `Uint8Array` into the module heap at `pointer`.
 *
 * The Kotlin side converts its own byte storage to a typed array before calling
 * this, keeping the boundary free of Kotlin array types.
 */
export function hbWriteBytes(pointer, bytes) {
    requireModule().HEAPU8.set(bytes, pointer);
}

/** Creates a blob by copying `length` bytes already written at `pointer`. */
export function hbBlobCreate(pointer, length) {
    // HB_MEMORY_MODE_DUPLICATE = 0: HarfBuzz copies, so the caller may free `pointer`.
    return requireModule()._hb_blob_create(pointer, length, 0, 0, 0);
}

export function hbBlobDestroy(blob) {
    requireModule()._hb_blob_destroy(blob);
}

export function hbFaceCreate(blob, index) {
    return requireModule()._hb_face_create(blob, index);
}

export function hbFaceDestroy(face) {
    requireModule()._hb_face_destroy(face);
}

export function hbFaceUpem(face) {
    return requireModule()._hb_face_get_upem(face);
}

export function hbFaceMakeImmutable(face) {
    requireModule().ccall('hb_face_make_immutable', null, ['number'], [face]);
}

export function hbFontCreate(face) {
    return requireModule()._hb_font_create(face);
}

export function hbFontDestroy(font) {
    requireModule()._hb_font_destroy(font);
}

export function hbFontSetScale(font, x, y) {
    requireModule()._hb_font_set_scale(font, x, y);
}

export function hbOtFontSetFuncs(font) {
    requireModule().ccall('hb_ot_font_set_funcs', null, ['number'], [font]);
}

export function hbFontMakeImmutable(font) {
    requireModule().ccall('hb_font_make_immutable', null, ['number'], [font]);
}

export function hbFontSetVarCoordsNormalized(font, pointer, count) {
    requireModule().ccall(
        'hb_font_set_var_coords_normalized', null,
        ['number', 'number', 'number'], [font, pointer, count],
    );
}

export function hbFontGlyphHAdvance(font, glyphId) {
    return requireModule().ccall('hb_font_get_glyph_h_advance', 'number', ['number', 'number'], [font, glyphId]);
}

export function hbFontGlyphVAdvance(font, glyphId) {
    return requireModule().ccall('hb_font_get_glyph_v_advance', 'number', ['number', 'number'], [font, glyphId]);
}

export function hbBufferCreate() {
    return requireModule()._hb_buffer_create();
}

export function hbBufferDestroy(buffer) {
    requireModule()._hb_buffer_destroy(buffer);
}

export function hbBufferAddUtf32(buffer, pointer, itemOffset, itemLength) {
    requireModule().ccall(
        'hb_buffer_add_utf32', null,
        ['number', 'number', 'number', 'number', 'number'],
        [buffer, pointer, itemLength, itemOffset, itemLength],
    );
}

export function hbBufferGuessSegmentProperties(buffer) {
    requireModule().ccall('hb_buffer_guess_segment_properties', null, ['number'], [buffer]);
}

export function hbBufferSetDirection(buffer, direction) {
    requireModule().ccall('hb_buffer_set_direction', null, ['number', 'number'], [buffer, direction]);
}

export function hbShape(font, buffer) {
    requireModule().ccall('hb_shape', null, ['number', 'number', 'number', 'number'], [font, buffer, 0, 0]);
}

export function hbBufferLength(buffer) {
    return requireModule()._hb_buffer_get_length(buffer);
}

const GLYPH_STRIDE_WORDS = 5;

export function hbBufferGlyphId(buffer, index) {
    const infos = requireModule()._hb_buffer_get_glyph_infos(buffer, 0);
    return requireModule().HEAPU32[(infos >> 2) + index * GLYPH_STRIDE_WORDS];
}

export function hbBufferGlyphCluster(buffer, index) {
    const infos = requireModule()._hb_buffer_get_glyph_infos(buffer, 0);
    return requireModule().HEAPU32[(infos >> 2) + index * GLYPH_STRIDE_WORDS + 2];
}

export function hbBufferGlyphXAdvance(buffer, index) {
    const positions = requireModule()._hb_buffer_get_glyph_positions(buffer, 0);
    return requireModule().HEAP32[(positions >> 2) + index * GLYPH_STRIDE_WORDS];
}

export function hbBufferGlyphYAdvance(buffer, index) {
    const positions = requireModule()._hb_buffer_get_glyph_positions(buffer, 0);
    return requireModule().HEAP32[(positions >> 2) + index * GLYPH_STRIDE_WORDS + 1];
}
